'use strict';
const $=id=>document.getElementById(id),send=d=>parent.postMessage(d,location.origin),canvas=$('board'),ctx=canvas.getContext('2d'),reduced=matchMedia('(prefers-reduced-motion: reduce)');let lane=2,state='idle',balance=0,connected=false,pending=false,roundId='',path=null,clock=0,elapsed=0,index=0,history=[],trail=[],flashes=new Map();
function select(){for(const el of document.querySelectorAll('[data-lane]')){el.setAttribute('aria-pressed',Number(el.dataset.lane)===lane);el.disabled=state==='dropping'||pending}const busy=state==='dropping'||pending;$('launch').disabled=!connected||busy||balance<50;$('launch').textContent=busy?'弹珠飞行中…':balance<50?'积分不足':'释放弹珠 · 50 积分';$('message').textContent=balance<50&&!busy?'积分不足 50，可返回大厅玩扫雷赚取积分。':'落袋后自动到账，奖励包含本局投入。';}
for(const id of ['lanes','lane-controls']){$(id).innerHTML=Array.from({length:5},(_,i)=>`<button data-lane="${i}" aria-pressed="${i===lane}" aria-label="落球入口 ${i+1}">${id==='lanes'?'↓':i+1}</button>`).join('');$(id).onclick=e=>{const b=e.target.closest('[data-lane]');if(!b||state==='dropping'||pending)return;lane=Number(b.dataset.lane);select();};}
$('slots').innerHTML=PLINKO_MULT.map((m,i)=>`<div class="slot ${m>=3?'high':m>=1?'medium':''}" data-slot="${i}">${m}×</div>`).join('');
$('launch').onclick=()=>{if(!connected||pending||state==='dropping'||balance<50)return;pending=true;select();send({type:'plinko-drop',lane});};$('back').onclick=()=>send({type:'game-return'});
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==parent||!e.data)return;const d=e.data;if(d.type==='plinko-error'){pending=false;select();$('message').textContent=d.message;return}if(d.type!=='plinko-state')return;connected=true;pending=false;balance=d.balance;$('balance').textContent=balance.toLocaleString();if(d.path)path=d.path;elapsed=d.elapsed;clock=performance.now();if(d.roundId!==roundId){roundId=d.roundId;index=0;trail=[];flashes.clear();document.querySelectorAll('.slot').forEach(e=>e.classList.remove('hit'));}const changed=d.state!==state;state=d.state;if(state==='dropping'){lane=d.lane;$('status').textContent='弹跳中 / 自动结算';if(changed){$('result').className='';$('result').innerHTML='<span>下一次碰撞，会改变方向。</span><small>弹珠正在穿过钉阵…</small>';}}if(changed&&d.result){const r=d.result;$('status').textContent='已落袋 / '+r.multiplier+'×';$('result').className=r.amount>r.cost?'win':'';$('result').innerHTML=`<span>${r.multiplier}× · 到账 ${r.amount} 积分</span><small>本局净${r.amount>=r.cost?'得':'损失'} ${Math.abs(r.amount-r.cost)} 积分 · 奖励已自动入账</small>`;document.querySelector(`[data-slot="${r.slot}"]`).classList.add('hit');history.unshift(r);history=history.slice(0,6);$('history').innerHTML=history.map(h=>`<b title="到账 ${h.amount} 积分">${h.multiplier}×</b>`).join('');}select();});
function draw(now){const ratio=Math.min(devicePixelRatio||1,2),w=canvas.clientWidth,h=w*600/700;if(canvas.width!==Math.round(w*ratio)){canvas.width=Math.round(w*ratio);canvas.height=Math.round(h*ratio)}ctx.setTransform(canvas.width/700,0,0,canvas.height/600,0,0);ctx.clearRect(0,0,700,600);ctx.strokeStyle='#263043';ctx.lineWidth=1;for(let y=65;y<530;y+=47){ctx.beginPath();ctx.moveTo(35,y);ctx.lineTo(665,y);ctx.stroke()}let ball=[0,150+lane*100,28,-1];if(path&&state!=='idle'){const time=(elapsed+(state==='dropping'?Math.max(0,now-clock):0))/1000;while(index<path.frames.length-1&&path.frames[index+1][0]<=time){index++;const f=path.frames[index];if(f[3]>=0)flashes.set(f[3],now)}const a=path.frames[index],b=path.frames[Math.min(index+1,path.frames.length-1)],t=b[0]>a[0]?Math.min(1,Math.max(0,(time-a[0])/(b[0]-a[0]))):0;ball=[time,a[1]+(b[1]-a[1])*t,a[2]+(b[2]-a[2])*t];}
for(let i=0;i<PLINKO_PEGS.length;i++){const p=PLINKO_PEGS[i],age=now-(flashes.get(i)??-1000),hit=age<260;ctx.fillStyle=hit?'#ffcd6c':'#a5adbf';ctx.beginPath();ctx.arc(p.x,p.y,hit&&!reduced.matches?6.5:4.5,0,Math.PI*2);ctx.fill();if(hit&&!reduced.matches){ctx.strokeStyle=`rgba(255,188,65,${1-age/260})`;ctx.beginPath();ctx.arc(p.x,p.y,7+age/20,0,Math.PI*2);ctx.stroke()}}
if(state==='dropping'&&!reduced.matches){trail.push([ball[1],ball[2]]);if(trail.length>12)trail.shift();trail.forEach(([x,y],i)=>{ctx.fillStyle=`rgba(255,170,37,${i/trail.length*.35})`;ctx.beginPath();ctx.arc(x,y,2+i*.45,0,Math.PI*2);ctx.fill()})}ctx.fillStyle='#ffb52d';ctx.beginPath();ctx.arc(ball[1],ball[2],8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff3cc';ctx.beginPath();ctx.arc(ball[1]-2,ball[2]-2,3,0,Math.PI*2);ctx.fill();requestAnimationFrame(draw);}
select();requestAnimationFrame(draw);send({type:'plinko-ready'});
